import{F as e,I as t,R as n,et as r,n as i}from"./chunks/framework.Bs4wm_X5.js";import{d as a}from"./chunks/theme.68gskFdW.js";import{vr as o}from"./chunks/assets.BpWoSz4B.js";var s=JSON.parse(`{"title":"Intervals","description":"Different kinds of relations between two notes","frontmatter":{"title":"Intervals","description":"Different kinds of relations between two notes","cover":"guang-yang.jpg","date":"2021-09-15T00:00:00.000Z"},"headers":[],"relativePath":"theory/intervals/index.md","filePath":"theory/intervals/index.md","lastUpdated":1790064412000}`),c={name:`theory/intervals/index.md`};function l(i,s,c,l,u,d){let f=a;return r(),e(`div`,null,[s[0]||=t(`<p><img src="`+o+`" alt="svg" width="312" height="312"></p><p>Two notes sounding simultaneously or sequentially form the basic building block for all the emotional expressiveness of music. They form some kind of relationships that bring up some distinct feeling.</p><p>The most basic is the 1:2 ratio of an <a href="./unison-octave/">Unison and octave</a>, that are foundational for cyclic nature of pitch class space. <a href="./fifth-fourth/">Perfect Fifth and Fourth</a> are the foundational consonances that bring joy of the simple 2:3 and 3:4 ratios. This is the root of the 12 note system as a whole.</p><p><a href="./third-sixth/">Thirds and Sixth</a> are the imperfect consonances to evoke deeper feelings while the <a href="./second-seventh/">Seconds and Sevenths</a> are the sharper dissonances to spice everything up. We&#39;ll explore the process of the <a href="./emancipation/">Emancipation of dissonance</a> to find out how did we get at this point in our pitch pairs interpretation. And take a brief look at some mathematical implications of building <a href="./cycles/">interval chains</a>.</p>`,4),n(f,{video:`3sUpoSTy8zw`}),n(f,{video:`cyW5z-M2yzw`})])}var u=i(c,[[`render`,l]]);export{s as __pageData,u as default};